Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Notation "'u'" := bv_unsigned (only parsing).

Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

Definition wr4 (m : word -> option byte) (a v : Z) : word -> option byte := wbytes m (Z_to_bv 64 a) (word_to_le_bytes 4 (Z_to_bv 64 v)).

(* [comment removed for export] *)
Definition SGP4 (m : word -> option byte) (a1 a2 a3 a4 sy sx cy cx : Z) : word -> option byte :=
  wr4 (wr4 (wr4 (wr4 (wr4 (wr4 (wr4 (wr4 m a1 0) a2 0) a3 0) a4 0) a1 sy) a2 sx) a3 cy) a4 cx.
Definition SGP2 (m : word -> option byte) (a1 a2 sy sx : Z) : word -> option byte :=
  wr4 (wr4 (wr4 (wr4 m a1 0) a2 0) a1 sy) a2 sx.

Lemma wr4_out : forall m a v (x : word), (0 <= a)%Z -> (a + 4 <= 2 ^ 64)%Z -> ~ (a <= u x < a + 4)%Z -> wr4 m a v x = m x.
