Lemma wr4_rd_out : forall m a v (b : Z) (n : nat), (0 <= a)%Z -> (a + 4 <= 2 ^ 64)%Z -> (0 <= b)%Z -> (b + Z.of_nat n < 2 ^ 64)%Z ->
